// Excerpt from RunAttachAvatarEx(_chr, _avt, ...): enable the character's
// Fighting Spirit slot, temporarily unlock it, attach the named Fighting Spirit,
// then restore whatever lock state it had before.
local partyHandle = CMND_GET_PARTY_HANDLE(_chr);
local wasLocked = CMND_GET_AVATAR_LOCK_FLAG(partyHandle);
CMND_SET_AVATAR_ENABLE(partyHandle, true);
CMND_SET_AVATAR_LOCK_FLAG(partyHandle, false);
CMND_ATTACH_AVATAR(_chr, _avt);
CMND_SET_AVATAR_LOCK_FLAG(partyHandle, wasLocked);

// Custom helper: attach a Fighting Spirit but keep whatever evolution
// progress was already stored for this character (skip the reset step
// by passing 0 as the third argument).
local ReattachAvatarKeepProgress = function (_chr, _avt)
{
	local attached = CMND_ATTACH_AVATAR(_chr, _avt, 0);
	if (attached == null)
	{
		// Character or Fighting Spirit name could not be resolved.
	}
	return attached;
};
